import CoreData

/// An entity managed by a `Database`.
///
/// The protocol imposes no identifier: entities with a business key adopt
/// `IdentifiableDatabaseObject` on top of it. What it does require is the schema the entity belongs
/// to, and the typed query and sort types its fetches are expressed with — usually generated by the
/// `@Entity` macro, or written by hand following the same shape.
///
public protocol DatabaseObject: NSManagedObject {

    /// The schema the entity belongs to. Every helper takes a `DatabaseContext<Schema>`.
    associatedtype Schema: DatabaseSchema

    /// The entity at the root of the entity's hierarchy, which the conformance — and so `Query`,
    /// `Sort` and the assignments — belongs to: the entity itself, unless it inherits from
    /// another entity. A non-final class can conform to the protocol because its requirements are
    /// tied to the root rather than to `Self`, which a subclass would not equal.
    associatedtype RootEntity: DatabaseObject = Self

    /// The typed predicate of the entity, resolved by implicit member: `.name("x")`, `.score(.greaterThan(2))`.
    associatedtype Query: EntityQuery where Query.Root == RootEntity

    /// The typed sort descriptor of the entity: `.name`, `.createdAt.descending`.
    associatedtype Sort: EntitySort where Sort.Root == RootEntity

    /// The typed attribute values of the entity, for batch requests too: `.name("x")`, `.order(3)`.
    /// `@Entity` generates it; entities without it write values by key.
    associatedtype AttributeAssignment: EntityAttributeAssignment = UntypedAttributeAssignment<Self> where AttributeAssignment.Root == RootEntity

    /// The typed values of the entity written on one object, attributes and relationships:
    /// `.name("x")`, `.reel(reel)`. `@Entity` generates it.
    associatedtype Assignment: EntityAssignment = UntypedAssignment<Self> where Assignment.Root == RootEntity

    /// The attributes and relationships of the entity in their stored form, one `Column` per
    /// member: `Note.Columns.text`. `@Entity` generates it; the generic APIs take key paths into it
    /// (`\.text`), their root inferred.
    associatedtype Columns = NoColumns

    /// Called after the object's values were rewritten in bulk (`update(with:)`), so that
    /// derived caches can be dropped. Does nothing by default.
    func didUpdate()

    /// Called once a new object was inserted by `create(id:in:)` or `fetchOrCreate(id:in:)`, its
    /// identifier set — unlike `awakeFromInsert()`, which runs before. Does nothing by default.
    func didCreate()
}

extension DatabaseObject {

    /// Inserts a new object in a context of the entity's schema.
    public init(context: DatabaseContext<Schema>) {
        self.init(context: context.nsContext)
    }

    /// The Core Data entity name, by convention the class name.
    public static var entityName: String {
        // `self`, the dynamic type: called through a metatype (`let type: Entry.Type = GearEntry.self`),
        // `Self` is the static one and would name the parent entity.
        String(describing: self)
    }

    public func didUpdate() { }

    public func didCreate() { }

    /// Whether the entity is abstract in the context's model: only its sub-entities have objects.
    public static func isAbstract(in context: DatabaseContext<Schema>) -> Bool {
        NSEntityDescription.entity(forEntityName: entityName, in: context.nsContext)?.isAbstract ?? false
    }
}

/// The `Columns` of an entity that declares none.
public enum NoColumns { }
